1	/**
2	 * Rule-based comment redaction (ADR 0001, ADR 0009).
3	 * Runs at store time in the Submission Worker so that no raw comment is ever kept at rest.
4	 */
5	
6	export type RosterItem =
7	  | string
8	  | {
9	      readonly name?: string | null | undefined;
10	      readonly firstName?: string | null | undefined;
11	      readonly lastName?: string | null | undefined;
12	      readonly email?: string | null | undefined;
13	    };
14	
15	export type Roster = ReadonlyArray<RosterItem>;
16	
17	const URL_PATTERN = /(?:https?:\/\/|www\.)[^\s<>"'()[\]{},]+(?<![.,!?:;])/gi;
18	const EMAIL_PATTERN = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/gi;
19	const HANDLE_PATTERN = /(?:^|(?<=[^\w@]))@[A-Za-z0-9_]+(?=[^\w]|$)/g;
20	
21	// German numbers: +49 / 0049 / national 0, optional "(0)" trunk after +49, mobile 015x-017x or
22	// landline area code, then 1-6 digit groups with optional separators (space, -, /, " / ", " - ").
23	// Dots are not separators, so dates such as 12.11.2026 never match.
24	// Not preceded by a word character, "+" or digit; not followed by a word character or [.,]\d.
25	const GERMAN_PHONE_PATTERN =
26	  /(?<![\w+])(?:(?:\+|00)49[ /-]?(?:\(0\) ?)?|\(?0)(?:1[5-7]\d|[2-9]\d{1,4})\)?(?:(?: [-/] |[ /-])?\d{1,6}){1,6}(?!\w|[.,]\d)/g;
27	
28	// 7+ digits with common separators (+, -, ., space, parentheses, slash)
29	const PHONE_PATTERN =
30	  /(?:^|(?<=[^\w+]))(?<!\d[./-])((?:\+\d{1,4}[-.\s]?)?(?:\(?\d{2,5}\)?[-.\s]?)(?:\d{2,5}[-.\s]?){1,4}\d{2,5})(?=[^\w]|$)/g;
31	
32	// A date or year range at the start of a generic phone match: kept, and only the rest is checked
33	const DATE_OR_YEAR_RANGE_PREFIX =
34	  /^(?:\d{1,2}\.\d{1,2}\.(?:\d{4}|\d{2})|\d{4}-\d{1,2}-\d{1,2}|\d{1,2}\/\d{1,2}\/\d{2,4}|\d{4} ?[-–] ?\d{4})(?!\d)/;
35	
36	const PHONE_SEPARATOR = /[-.\s()+]/;
37	
38	/**
39	 * Generic phone numbers: 7+ digits with separators. A match that starts with a date or a year
40	 * range keeps it, and the scan resumes right after it, so a number written after a date is still
41	 * caught. Never starts inside a number such as 1.2.2024.
42	 */
43	const redactGenericPhones = (text: string): string => {
44	  const pattern = new RegExp(PHONE_PATTERN.source, "g");
45	  let result = "";
46	  let kept = 0;
47	  for (let match = pattern.exec(text); match !== null; match = pattern.exec(text)) {
48	    const candidate = match[1] ?? "";
49	    const start = match.index + match[0].indexOf(candidate);
50	    const date = DATE_OR_YEAR_RANGE_PREFIX.exec(candidate)?.[0];
51	    if (date !== undefined) {
52	      pattern.lastIndex = start + date.length;
53	    } else if ((candidate.match(/\d/g) ?? []).length >= 7 && PHONE_SEPARATOR.test(candidate)) {
54	      result += text.slice(kept, start) + "[phone]";
55	      kept = start + candidate.length;
56	    }
57	  }
58	  return result + text.slice(kept);
59	};
60	
61	const INTERNATIONAL_GERMAN_PREFIX = /^(?:\+|00)49/;
62	
63	// Significant national digits: without the +49/0049 prefix, the "(0)" trunk, or the national leading 0
64	const germanSignificantDigits = (match: string): number => {
65	  const international = INTERNATIONAL_GERMAN_PREFIX.test(match);
66	  const body = match.replace(INTERNATIONAL_GERMAN_PREFIX, "").replace("(0)", "");
67	  const digits = (body.match(/\d/g) ?? []).length;
68	  return international ? digits : digits - 1;
69	};
70	
71	const stripDiacritics = (text: string): string =>
72	  text
73	    .normalize("NFKD")
74	    .replace(/[\u0300-\u036f]/g, "")
75	    .toLowerCase();
76	
77	interface CandidateName {
78	  readonly norm: string;
79	  readonly words: ReadonlyArray<string>;
80	  readonly wordCount: number;
81	}
82	
83	const extractCandidateNames = (roster: Roster): ReadonlyArray<CandidateName> => {
84	  const rawNames = new Set<string>();
85	
86	  for (const item of roster) {
87	    if (typeof item === "string") {
88	      const trimmed = item.trim();
89	      if (trimmed.includes("@")) {
90	        const localPart = trimmed.split("@")[0] ?? "";
91	        if (localPart) {
92	          rawNames.add(localPart);
93	          for (const sub of localPart.split(/[._-]/)) {
94	            if (sub) rawNames.add(sub);
95	          }
96	        }
97	      } else {
98	        rawNames.add(trimmed);
99	        for (const sub of trimmed.split(/\s+/)) {
100	          if (sub) rawNames.add(sub);
101	        }
102	      }
103	    } else if (item && typeof item === "object") {
104	      if (item.name) {
105	        rawNames.add(item.name.trim());
106	        for (const sub of item.name.trim().split(/\s+/)) {
107	          if (sub) rawNames.add(sub);
108	        }
109	      }
110	      if (item.firstName) rawNames.add(item.firstName.trim());
111	      if (item.lastName) rawNames.add(item.lastName.trim());
112	      if (item.email) {
113	        const localPart = item.email.trim().split("@")[0] ?? "";
114	        if (localPart) {
115	          rawNames.add(localPart);
116	          for (const sub of localPart.split(/[._-]/)) {
117	            if (sub) rawNames.add(sub);
118	          }
119	        }
120	      }
121	    }
122	  }
123	
124	  const seen = new Set<string>();
125	  const candidates: Array<CandidateName> = [];
126	
127	  for (const name of rawNames) {
128	    const norm = stripDiacritics(name.trim());
129	    if (norm.length < 2 || seen.has(norm)) continue;
130	    seen.add(norm);
131	
132	    const words = norm.split(/\s+/).filter((w) => w.length > 0);
133	    if (words.length > 0) {
134	      candidates.push({
135	        norm,
136	        words,
137	        wordCount: words.length,
138	      });
139	    }
140	  }
141	
142	  // Greedy match: multi-word names first, then longer names
143	  return candidates.sort((a, b) => b.wordCount - a.wordCount || b.norm.length - a.norm.length);
144	};
145	
146	const redactNames = (text: string, candidates: ReadonlyArray<CandidateName>): string => {
147	  if (candidates.length === 0) return text;
148	
149	  const segmenter = new Intl.Segmenter("en", { granularity: "word" });
150	  const segments = [...segmenter.segment(text)];
151	
152	  let result = "";
153	  let i = 0;
154	
155	  while (i < segments.length) {
156	    const seg = segments[i];
157	    if (seg === undefined) break;
158	
159	    if (!seg.isWordLike) {
160	      result += seg.segment;
161	      i++;
162	      continue;
163	    }
164	
165	    let matched = false;
166	
167	    for (const candidate of candidates) {
168	      if (candidate.wordCount > 1) {
169	        // Multi-word name lookahead
170	        let wordIdx = i;
171	        let matchedCount = 0;
172	        let spanEnd = i;
173	        const collectedWords: Array<string> = [];
174	        let possessiveSuffix = "";
175	
176	        while (wordIdx < segments.length && matchedCount < candidate.wordCount) {
177	          const nextSeg = segments[wordIdx];
178	          if (nextSeg === undefined) break;
179	          if (nextSeg.isWordLike) {
180	            let segWord = nextSeg.segment;
181	            if (matchedCount === candidate.wordCount - 1) {
182	              if (segWord.endsWith("'s") || segWord.endsWith("’s")) {
183	                possessiveSuffix = segWord.slice(-2);
184	                segWord = segWord.slice(0, -2);
185	              }
186	            }
187	            collectedWords.push(stripDiacritics(segWord));
188	            matchedCount++;
189	            spanEnd = wordIdx;
190	          }
191	          wordIdx++;
192	        }
193	
194	        if (matchedCount === candidate.wordCount && collectedWords.join(" ") === candidate.words.join(" ")) {
195	          result += "[name]" + possessiveSuffix;
196	          i = spanEnd + 1;
197	          matched = true;
198	          break;
199	        }
200	      } else {
201	        // Single word candidate
202	        let word = seg.segment;
203	        let suffix = "";
204	        if (word.endsWith("'s") || word.endsWith("’s")) {
205	          suffix = word.slice(-2);
206	          word = word.slice(0, -2);
207	        }
208	
209	        if (stripDiacritics(word) === candidate.norm) {
210	          result += "[name]" + suffix;
211	          i++;
212	          matched = true;
213	          break;
214	        }
215	      }
216	    }
217	
218	    if (!matched) {
219	      result += seg.segment;
220	      i++;
221	    }
222	  }
223	
224	  return result;
225	};
