227	/**
228	 * Pure function to redact identifying info (URLs, emails, handles, phone numbers, and roster names)
229	 * from comments according to ADR 0001 and ADR 0009.
230	 */
231	export const redact = (text: string, roster: Roster): string => {
232	  if (!text) return "";
233	
234	  // 1,000-character limit counted after Unicode normalization
235	  const normalized = text.normalize("NFC");
236	  const bounded = normalized.length > 1000 ? normalized.slice(0, 1000) : normalized;
237	
238	  // 1. Redact URLs
239	  let result = bounded.replace(URL_PATTERN, "[link]");
240	
241	  // 2. Redact Email addresses
242	  result = result.replace(EMAIL_PATTERN, "[email]");
243	
244	  // 3. Redact @handles
245	  result = result.replace(HANDLE_PATTERN, "[handle]");
246	
247	  // 4. Redact German phone numbers (7-12 significant national digits, unseparated numbers included)
248	  result = result.replace(GERMAN_PHONE_PATTERN, (match: string) => {
249	    const digits = germanSignificantDigits(match);
250	    return digits >= 7 && digits <= 12 ? "[phone]" : match;
251	  });
252	
253	  // 5. Redact Phone numbers (7+ digits with separators, keeping plain numbers and dates)
254	  result = redactGenericPhones(result);
255	
256	  // 6. Redact roster names
257	  const candidates = extractCandidateNames(roster);
258	  result = redactNames(result, candidates);
259	
260	  return result;
261	};
